// Independent read-only post-apply audit of all eight batches; never mutates data.
import fs from 'node:fs';import path from 'node:path';import crypto from 'node:crypto';import assert from 'node:assert/strict';import {createRequire} from 'node:module';import {isDeepStrictEqual as equal} from 'node:util';const root=process.cwd(),dir='docs/audits/jpn_dp4_identity80_20261119',require=createRequire(`${root}/backend/package.json`),cfg=require('dotenv').parse(fs.readFileSync(path.join(root,'.env.local'))),ref='ycdxbpibncqcchqiihfz',url=new URL(cfg.SUPABASE_DB_URL);assert.equal(new URL(cfg.SUPABASE_URL).hostname,`${ref}.supabase.co`);assert.ok(`${url.hostname} ${decodeURIComponent(url.username)}`.includes(ref));assert.match(fs.readFileSync('supabase/config.toml','utf8'),new RegExp(`project_id\\s*=\\s*"${ref}"`));const planBytes=fs.readFileSync(`${dir}/identity80-execution-plan-20261119.json`),sha=b=>crypto.createHash('sha256').update(b).digest('hex'),pin='027945b5f54f987ce1972ed476a523ed99c67ff7a7723d510ac8258c7cabe37e';assert.equal(sha(planBytes),pin);const plan=JSON.parse(planBytes);assert.equal(plan.rows.length,80);const ids=plan.rows.map(x=>x.parent_before.id),{Client}=require('pg'),db=new Client({connectionString:cfg.SUPABASE_DB_URL,connectionTimeoutMillis:10000});await db.connect();try{await db.query('begin isolation level repeatable read read only');await db.query("set local statement_timeout='60s'");const sanity=(await db.query("select current_setting('transaction_read_only') read_only,(select count(*)::int from public.card_prints) parents,(select count(*)::int from public.sets) sets,(select count(*)::int from public.card_print_traits) traits")).rows[0];assert.equal(sanity.read_only,'on');assert.ok(sanity.parents>=40000&&sanity.sets>=150&&sanity.traits>=5000);const q=async(sql,args)=>(await db.query(sql,args)).rows,parents=(await q('select to_jsonb(p) row from public.card_prints p where p.id=any($1::uuid[])',[ids])).map(x=>x.row),identities=(await q(`select to_jsonb(i) row,public.card_print_identity_hash_v1(i.identity_domain,i.identity_key_version,i.set_code_identity,i.printed_number,i.normalized_printed_name,i.source_name_raw,i.identity_payload) computed from public.card_print_identity i where i.card_print_id=any($1::uuid[])`,[ids])),links=(await q('select to_jsonb(l) row from public.card_print_species l where l.card_print_id=any($1::uuid[])',[ids])).map(x=>x.row),species=(await q('select to_jsonb(s) row from public.pokemon_species s where s.id=any($1::uuid[])',[plan.rows.map(x=>x.species_before.id)])).map(x=>x.row),receipts=await q(`select id::text,payload from public.raw_imports where source='grookai_jpn_dp4_identity80_v1' and payload->>'package_fingerprint'=$1 and payload->>'_kind'='dp4_identity80_receipt' order by (payload->>'chunk')::int`,[pin]);assert.equal(parents.length,80);assert.equal(identities.length,80);assert.equal(links.length,80);assert.equal(species.length,80);assert.equal(receipts.length,8);assert.deepEqual(receipts.map(r=>r.payload.chunk),[0,1,2,3,4,5,6,7]);const sources=await q(`select id::text,payload from public.raw_imports where source='grookai_jpn_dp4_identity80_v1' and id=any($1::bigint[])`,[receipts.map(r=>r.payload.source_snapshot_raw_import_id)]);assert.equal(sources.length,8);const byId=a=>new Map(a.map(x=>[x.id,x])),pidx=byId(parents),iidx=new Map(identities.map(x=>[x.row.id,x])),lidx=byId(links),sidx=byId(species);for(const [chunk,receipt] of receipts.entries()){const part=plan.rows.slice(chunk*10,chunk*10+10),raw=sources.find(x=>x.id===receipt.payload.source_snapshot_raw_import_id)?.payload;assert.ok(raw);assert.equal(raw.package_fingerprint,pin);assert.equal(raw.chunk,chunk);assert.equal(raw.run_id,receipt.payload.run_id);assert.equal(raw.writer_fingerprint,receipt.payload.writer_fingerprint);assert.ok(equal(raw.rows,part));assert.equal(raw.sources.length,10);for(const r of part){const parent=pidx.get(r.parent_before.id),ii=iidx.get(r.identity_before.id),link=lidx.get(r.primary_link_before.id),sp=sidx.get(r.species_before.id);assert.ok(equal(parent,r.parent_before));assert.ok(equal(link,r.primary_link_before));assert.ok(equal(sp,r.species_before));assert.equal(ii.computed,r.identity_before.identity_key_hash);const actual=structuredClone(ii.row),expected=structuredClone(r.identity_before);delete actual.updated_at;delete expected.updated_at;expected.identity_payload={...expected.identity_payload,card_name_en_candidates:[r.expected.en],normalized_family_name_candidates:[r.expected.en.toLowerCase()],catalog_dp4_english_identity_repair_v1:{package_fingerprint:pin,official_card_id:r.source.official_id,official_image_sha256:r.source.image_sha256,original_claims_preserved_in_raw:true}};assert.ok(equal(actual,expected),`identity postimage drift ${r.gv_id}`);const source=raw.sources.find(x=>x.official_id===r.source.official_id);assert.ok(source);assert.equal(sha(Buffer.from(source.page_base64,'base64')),r.source.official_page_sha256);assert.equal(sha(Buffer.from(source.image_base64,'base64')),r.source.image_sha256);}}await db.query('rollback');const out={version:'JPN_DP4_IDENTITY80_INDEPENDENT_READBACK_V1',verified_at:new Date().toISOString(),status:'passed',scope:'Separate read-only database snapshot; checks 80 parent, identity, species-link and species postimages plus eight receipt/source packages.',sanity,records:80,chunks:8,receipt_ids:receipts.map(x=>x.id)};fs.writeFileSync(`${dir}/independent-identity80-readback-20261119.json`,JSON.stringify(out,null,2)+'\n',{flag:'wx'});console.log(JSON.stringify(out));}finally{await db.end()}
